"""Build the portable FlyingRoots website using only Python's standard library."""
from pathlib import Path
import json
import html
import shutil

ROOT = Path(__file__).resolve().parent.parent
DIST = ROOT / 'dist'
data = json.loads((ROOT / 'source/catalogue.json').read_text())
def esc(value): return html.escape(str(value), quote=True)
def icon(name, cls=''):
    return f'<svg class="icon {cls}" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#i-{name}"></use></svg>'
def pic(name, alt, cls='', eager=False):
    return f'<img src="./images/{name}.webp" alt="{esc(alt)}" width="1536" height="1024" loading="{"eager" if eager else "lazy"}" decoding="async" fetchpriority="low" class="{cls}">'
def label(text): return f'<p class="eyebrow">{text}</p>'
def button(text, href, variant='green', extra=''):
    return f'<a class="button {variant}" href="{href}" {extra}>{text}</a>'
